/**
 * DMS Protocol Node
 * 通訊協定管理（列表、新增、編輯、刪除）
 */

module.exports = function(RED) {
    "use strict";
    const axios = require('axios');

    // DMS API 配置
    const secretKey = 'da6e6728-b51c-11ea-ac59-00ff7ae2c9c8';
    const requester = 'admin';

    // 簽名函數
    async function getSignData(baseUrl, userToken, url, method, params) {
        try {
            const response = await axios.post(
                `${baseUrl}/schideron/openApi/auth/sign`,
                {
                    requester,
                    url,
                    method,
                    params
                },
                {
                    headers: {
                        'Authorization': `Bearer ${userToken}`,
                        'Content-Type': 'application/json;charset=utf-8',
                        'secretKey': secretKey
                    }
                }
            );

            if ([1005, 1006].includes(response.data.code)) {
                throw new Error(response.data.message);
            }
            return response.data;
        } catch (error) {
            throw error;
        }
    }

    function DMSProtocolNode(config) {
        RED.nodes.createNode(this, config);
        const node = this;

        node.on('input', async function(msg) {
            try {
                // 從 config 或 msg 取得設定
                const baseUrl = config.baseUrl || msg.baseUrl || 'http://101.35.85.65:8082';
                const token = config.token || msg.token || '';
                const action = config.action || msg.action || 'list';

                if (!token) {
                    node.error('Token is required');
                    node.status({fill:"red", shape:"ring", text:"missing token"});
                    return;
                }

                node.status({fill:"blue", shape:"dot", text:action + "..."});

                let url, method, params, data, response;

                switch (action) {
                    case 'list':
                        // 取得列表
                        url = '/schideron/openApi/protocol/list';
                        method = 'GET';
                        params = {
                            type: config.protocolType || msg.protocolType || msg.type || '',
                            keyword: config.keyword || msg.keyword || '',
                            pageNum: config.pageNum || msg.pageNum || '1',
                            limit: config.limit || msg.limit || '10',
                            requester
                        };

                        const signDataList = await getSignData(baseUrl, token, url, method, params);

                        response = await axios.get(`${baseUrl}${url}`, {
                            params,
                            headers: {
                                'Authorization': `Bearer ${token}`,
                                'Content-Type': 'application/json',
                                'secretKey': secretKey,
                                'sign': signDataList.sign,
                                't': signDataList.t
                            }
                        });

                        if (response.data.status === 'SUCCESS') {
                            msg.payload = response.data.pageInfo;
                        }
                        break;

                    case 'add':
                        // 新增協定
                        url = '/schideron/openApi/protocol/add';
                        method = 'POST';
                        data = {
                            name: msg.payload.name || msg.name,
                            type: msg.payload.type || msg.protocolType,
                            gatewayId: msg.payload.gatewayId || msg.gatewayId,
                            gatewayIp: msg.payload.gatewayIp || msg.gatewayIp,
                            requester
                        };

                        // 添加可選欄位
                        if (msg.payload.subscribeType || msg.subscribeType) {
                            data.subscribeType = msg.payload.subscribeType || msg.subscribeType;
                        }
                        if (msg.payload.mqttUser || msg.mqttUser) {
                            data.mqttUser = msg.payload.mqttUser || msg.mqttUser;
                        }
                        if (msg.payload.mqttPW || msg.mqttPW) {
                            data.mqttPW = msg.payload.mqttPW || msg.mqttPW;
                        }
                        if (msg.payload.mqttServerAddr || msg.mqttServerAddr) {
                            data.mqttServerAddr = msg.payload.mqttServerAddr || msg.mqttServerAddr;
                        }

                        const signDataAdd = await getSignData(baseUrl, token, url, method, data);

                        response = await axios.post(`${baseUrl}${url}`, data, {
                            headers: {
                                'Authorization': `Bearer ${token}`,
                                'Content-Type': 'application/json',
                                'secretKey': secretKey,
                                'sign': signDataAdd.sign,
                                't': signDataAdd.t
                            }
                        });

                        if (response.data.status === 'SUCCESS') {
                            msg.payload = response.data;
                        }
                        break;

                    case 'edit':
                        // 編輯協定
                        const editId = msg.payload.id || msg.id || config.protocolId;
                        if (!editId) {
                            throw new Error('ID is required for edit action');
                        }

                        url = `/schideron/openApi/protocol/edit/${editId}`;
                        method = 'PUT';
                        data = {
                            name: msg.payload.name || msg.name,
                            type: msg.payload.type || msg.protocolType,
                            gatewayId: msg.payload.gatewayId || msg.gatewayId,
                            gatewayIp: msg.payload.gatewayIp || msg.gatewayIp,
                            requester
                        };

                        // 添加可選欄位
                        if (msg.payload.enabled !== undefined) {
                            data.enabled = msg.payload.enabled;
                        }

                        const signDataEdit = await getSignData(baseUrl, token, url, method, data);

                        response = await axios.put(`${baseUrl}${url}`, data, {
                            headers: {
                                'Authorization': `Bearer ${token}`,
                                'Content-Type': 'application/json',
                                'secretKey': secretKey,
                                'sign': signDataEdit.sign,
                                't': signDataEdit.t
                            }
                        });

                        if (response.data.status === 'SUCCESS') {
                            msg.payload = response.data;
                        }
                        break;

                    case 'delete':
                        // 刪除協定
                        const deleteId = msg.payload.id || msg.id || config.protocolId;
                        if (!deleteId) {
                            throw new Error('ID is required for delete action');
                        }

                        url = `/schideron/openApi/protocol/delete/${deleteId}`;
                        method = 'DELETE';
                        params = { requester };

                        const signDataDelete = await getSignData(baseUrl, token, url, method, params);

                        response = await axios.delete(`${baseUrl}${url}`, {
                            headers: {
                                'Authorization': `Bearer ${token}`,
                                'Content-Type': 'application/json',
                                'secretKey': secretKey,
                                'sign': signDataDelete.sign,
                                't': signDataDelete.t
                            }
                        });

                        if (response.data.status === 'SUCCESS') {
                            msg.payload = response.data;
                        }
                        break;

                    default:
                        throw new Error('Unknown action: ' + action);
                }

                node.status({fill:"green", shape:"dot", text:"success"});
                node.send(msg);

            } catch (error) {
                node.error(error.message);
                node.status({fill:"red", shape:"ring", text:"error"});
                msg.payload = {
                    error: error.message
                };
                node.send(msg);
            }
        });
    }

    RED.nodes.registerType("dms-protocol-list", DMSProtocolNode);
}
